SELECT float32 = uint64 AS c0, toTypeName(float32 = uint64) AS t0, float32 != uint64 AS c1, toTypeName(float32 != uint64) AS t1, float32 < uint64 AS c2, toTypeName(float32 < uint64) AS t2, float32 <= uint64 AS c3, toTypeName(float32 <= uint64) AS t3, float32 > uint64 AS c4, toTypeName(float32 > uint64) AS t4, float32 >= uint64 AS c5, toTypeName(float32 >= uint64) AS t5 FROM he24.numeric ORDER BY row_id
